const inspector = require("node:inspector");

function attempt(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

module.exports = async function probeInspector() {
  const results = {
    session: attempt(() => {
      const session = new inspector.Session();
      session.connect();
      session.post("Runtime.enable");
      session.disconnect();
    }),
    listener: attempt(() => {
      inspector.open(0, "127.0.0.1", false);
      const active = inspector.url() !== undefined;
      inspector.close();
      if (!active) throw new Error("inspector listener did not start");
    }),
  };
  await Promise.resolve();
  results.promiseSession = attempt(() => {
    const session = new inspector.Session();
    session.connect();
    session.disconnect();
  });
  return results;
};
